SELECT 'verified-wallet-users', 'List KYC-Verified Wallet Users', 'code', 'Easy', 'Fintech',
       'Filtering', ARRAY['select','where']::text[], 'Compliance needs a list of all KYC-verified wallet users.

Return `user_id`, `name`, and `district` of every user whose KYC is verified, ordered by `user_id`.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), 'SELECT user_id, name, district FROM users WHERE kyc_verified = true ORDER BY user_id;',
       '["kyc_verified is a boolean column","Filter with WHERE, then ORDER BY user_id"]'::jsonb, '[]'::jsonb, NULL,
       NULL, 0, NULL, 82
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'verified-wallet-users');

