SELECT 'large-successful-transactions', 'Large Successful Transactions', 'code', 'Easy', 'Fintech',
       'Filtering', ARRAY['where','and']::text[], 'The risk team monitors big movements. Return `txn_id`, `user_id`, `txn_type`, and `amount` for every **successful** transaction of more than ৳5,000, newest first.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), 'SELECT txn_id, user_id, txn_type, amount FROM transactions WHERE status = ''success'' AND amount > 5000 ORDER BY txn_at DESC;',
       '["Combine two conditions with AND","Newest first means ORDER BY txn_at DESC"]'::jsonb, '[]'::jsonb, NULL,
       NULL, 0, NULL, 78
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'large-successful-transactions');

