SELECT 'transactions-by-type', 'Transaction Mix by Type', 'code', 'Easy', 'Fintech',
       'Aggregation', ARRAY['group-by','count']::text[], 'Product wants the transaction mix. For each `txn_type`, return the type and the number of transactions (`txn_count`), highest count first.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), 'SELECT txn_type, COUNT(*) AS txn_count FROM transactions GROUP BY txn_type ORDER BY txn_count DESC;',
       '["GROUP BY txn_type","COUNT(*) counts rows per group"]'::jsonb, '[]'::jsonb, NULL,
       NULL, 0, NULL, 75
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'transactions-by-type');

INSERT INTO public.careerprep_questions
  (slug, title, question_type, difficulty, industry, category, tags, content_md,
   schema_sql, initial_sql, solution_sql, hints, options, correct_option,
   parent_id, order_index, time_limit_secs, success_rate)
SELECT 'agent-cash-out-volume', 'Cash-Out Volume per Agent', 'code', 'Medium', 'Fintech',
       'Joins', ARRAY['join','group-by','sum']::text[], 'Agent operations ranks agent points by the cash they pay out.

For each agent, return `shop_name`, `district`, and total **successful** `cash_out` amount as `total_cash_out`, highest first. Only include agents that have at least one successful cash-out.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), 'SELECT a.shop_name, a.district, SUM(t.amount) AS total_cash_out
FROM agents a
JOIN transactions t ON t.agent_id = a.agent_id
WHERE t.txn_type = ''cash_out'' AND t.status = ''success''
GROUP BY a.shop_name, a.district
ORDER BY total_cash_out DESC;',
       '["JOIN transactions to agents on agent_id","Filter type and status in WHERE before grouping","SUM(amount) per agent"]'::jsonb, '[]'::jsonb, NULL,
       NULL, 0, NULL, 61
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'agent-cash-out-volume');

INSERT INTO public.careerprep_questions
  (slug, title, question_type, difficulty, industry, category, tags, content_md,
   schema_sql, initial_sql, solution_sql, hints, options, correct_option,
   parent_id, order_index, time_limit_secs, success_rate)
SELECT 'daily-transaction-volume', 'Daily Transaction Volume (First Week of June)', 'code', 'Medium', 'Fintech',
       'Aggregation', ARRAY['date','group-by']::text[], 'Finance tracks daily volume. For 1–7 June 2026, return each day (`txn_date`) and the total amount of **successful** transactions (`daily_volume`), ordered by day.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), 'SELECT txn_at::date AS txn_date, SUM(amount) AS daily_volume
FROM transactions
WHERE status = ''success'' AND txn_at >= ''2026-06-01'' AND txn_at < ''2026-06-08''
GROUP BY txn_at::date
ORDER BY txn_date;',
       '["Cast the timestamp to a date with ::date","Bound the range with >= and <","GROUP BY the casted date"]'::jsonb, '[]'::jsonb, NULL,
       NULL, 0, NULL, 58
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'daily-transaction-volume');

INSERT INTO public.careerprep_questions
  (slug, title, question_type, difficulty, industry, category, tags, content_md,
   schema_sql, initial_sql, solution_sql, hints, options, correct_option,
   parent_id, order_index, time_limit_secs, success_rate)
SELECT 'users-with-clean-history', 'Users with a Clean Transaction History', 'code', 'Medium', 'Fintech',
       'Subqueries', ARRAY['not-exists','anti-join']::text[], 'Support wants users who have **never** had a failed or reversed transaction.

Return `user_id` and `name` of those users, ordered by `user_id`.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), 'SELECT u.user_id, u.name
FROM users u
WHERE NOT EXISTS (
  SELECT 1 FROM transactions t
  WHERE t.user_id = u.user_id AND t.status IN (''failed'',''reversed'')
)
ORDER BY u.user_id;',
       '["Think anti-join: users with no matching bad transaction","NOT EXISTS with a correlated subquery","status IN (''failed'',''reversed'')"]'::jsonb, '[]'::jsonb, NULL,
       NULL, 0, NULL, 49
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'users-with-clean-history');

INSERT INTO public.careerprep_questions
  (slug, title, question_type, difficulty, industry, category, tags, content_md,
   schema_sql, initial_sql, solution_sql, hints, options, correct_option,
   parent_id, order_index, time_limit_secs, success_rate)
SELECT 'top-payers', 'Top 3 Users by Payment Spend', 'code', 'Medium', 'Fintech',
       'Aggregation', ARRAY['group-by','limit','join']::text[], 'Merchant payments is the growth bet. Return the top 3 users by total successful `payment` amount: `name` and `total_paid`, highest first.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), 'SELECT u.name, SUM(t.amount) AS total_paid
FROM users u
JOIN transactions t ON t.user_id = u.user_id
WHERE t.txn_type = ''payment'' AND t.status = ''success''
GROUP BY u.name
ORDER BY total_paid DESC
LIMIT 3;',
       '["Join, filter to successful payments, group by user","ORDER BY ... DESC LIMIT 3"]'::jsonb, '[]'::jsonb, NULL,
       NULL, 0, NULL, 56
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'top-payers');

INSERT INTO public.careerprep_questions
  (slug, title, question_type, difficulty, industry, category, tags, content_md,
   schema_sql, initial_sql, solution_sql, hints, options, correct_option,
   parent_id, order_index, time_limit_secs, success_rate)
SELECT 'largest-transaction-per-user', 'Each User''s Largest Transaction', 'code', 'Hard', 'Fintech',
       'Window Functions', ARRAY['row-number','partition']::text[], 'For every user who has at least one successful transaction, return `name`, `txn_type`, and `amount` of their **single largest** successful transaction. Break amount ties by earliest `txn_at`. Order by `name`.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), 'SELECT name, txn_type, amount FROM (
  SELECT u.name, t.txn_type, t.amount,
         ROW_NUMBER() OVER (PARTITION BY u.user_id ORDER BY t.amount DESC, t.txn_at ASC) AS rn
  FROM users u
  JOIN transactions t ON t.user_id = u.user_id
  WHERE t.status = ''success''
) ranked
WHERE rn = 1
ORDER BY name;',
       '["ROW_NUMBER() OVER (PARTITION BY user ORDER BY amount DESC)","Wrap in a subquery and keep rn = 1","Tie-break inside the window''s ORDER BY"]'::jsonb, '[]'::jsonb, NULL,
       NULL, 0, 1800, 38
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'largest-transaction-per-user');

