SELECT 'agent-settlement-report', 'Case: Agent Settlement Report', 'case_study', 'Hard', 'Fintech',
       'Conditional Aggregation', ARRAY['case-when','group-by']::text[], '**Scenario.** Every evening, finance settles cash with agent points: cash-in raises the agent''s e-money balance, cash-out lowers it.

For each agent with successful activity, return `shop_name`, total successful cash-in (`cash_in_total`), total successful cash-out (`cash_out_total`), and `net_float` = cash_in − cash_out. Order by `net_float` descending.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), 'SELECT a.shop_name,
       SUM(CASE WHEN t.txn_type = ''cash_in''  THEN t.amount ELSE 0 END) AS cash_in_total,
       SUM(CASE WHEN t.txn_type = ''cash_out'' THEN t.amount ELSE 0 END) AS cash_out_total,
       SUM(CASE WHEN t.txn_type = ''cash_in''  THEN t.amount ELSE 0 END)
     - SUM(CASE WHEN t.txn_type = ''cash_out'' THEN t.amount ELSE 0 END) AS net_float
FROM agents a
JOIN transactions t ON t.agent_id = a.agent_id
WHERE t.status = ''success''
GROUP BY a.shop_name
ORDER BY net_float DESC;',
       '["One row per agent means one GROUP BY with conditional SUMs","SUM(CASE WHEN type=''cash_in'' THEN amount ELSE 0 END)","Net float is the difference of the two conditional sums"]'::jsonb, '[]'::jsonb, NULL,
       NULL, 0, 1800, 36
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'agent-settlement-report');

