  (slug, title, question_type, difficulty, industry, category, tags, content_md,
   schema_sql, initial_sql, solution_sql, hints, options, correct_option,
   parent_id, order_index, time_limit_secs, success_rate)
SELECT 'biggest-order-per-customer', 'Each Customer''s Biggest Order', 'code', 'Hard', 'E-Commerce',
       'Window Functions', ARRAY['window','rank']::text[], 'For every customer with at least one delivered order, return `name`, `order_id`, and the revenue of their **highest-revenue delivered order** (`order_revenue`). Order by revenue descending.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'ecommerce_shop'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'ecommerce_shop'), ''), 'SELECT name, order_id, order_revenue FROM (
  SELECT c.name, o.order_id, SUM(oi.quantity * oi.unit_price) AS order_revenue,
         ROW_NUMBER() OVER (PARTITION BY c.customer_id ORDER BY SUM(oi.quantity * oi.unit_price) DESC) AS rn
  FROM customers c
  JOIN orders o ON o.customer_id = c.customer_id
  JOIN order_items oi ON oi.order_id = o.order_id
  WHERE o.status = ''delivered''
  GROUP BY c.customer_id, c.name, o.order_id
) t
WHERE rn = 1
ORDER BY order_revenue DESC;',
       '["First compute revenue per order (GROUP BY)","Then ROW_NUMBER() partitioned by customer over that aggregate","Keep rn = 1"]'::jsonb, '[]'::jsonb, NULL,
       NULL, 0, 1800, 35
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'biggest-order-per-customer');

