SELECT 'stuck-parcels-aging', 'Aging Report for Stuck Parcels', 'code', 'Hard', 'Logistics',
       'Date Arithmetic', ARRAY['null','interval','left-join']::text[], 'As of **2026-06-06 00:00:00**, which picked-up parcels are still not delivered? Return `parcel_id`, rider `name`, delivery `status`, and `hours_in_flight` (hours from `picked_at` to that cutoff, rounded to 1 decimal), longest first. Include both in-transit and failed attempts that never delivered — but if a parcel was later delivered by another attempt, exclude it.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'logistics_courier'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'logistics_courier'), ''), 'SELECT d.parcel_id, r.name, d.status,
       ROUND((EXTRACT(EPOCH FROM (TIMESTAMP ''2026-06-06 00:00:00'' - d.picked_at)) / 3600)::numeric, 1) AS hours_in_flight
FROM deliveries d
JOIN riders r ON r.rider_id = d.rider_id
WHERE d.delivered_at IS NULL
  AND NOT EXISTS (
    SELECT 1 FROM deliveries d2
    WHERE d2.parcel_id = d.parcel_id AND d2.status = ''delivered''
  )
ORDER BY hours_in_flight DESC;',
       '["Undelivered attempts have delivered_at IS NULL","A parcel rescued by a later attempt must be excluded — NOT EXISTS","Hours = EPOCH difference / 3600 against the fixed cutoff"]'::jsonb, '[]'::jsonb, NULL,
       NULL, 0, 1800, 29
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'stuck-parcels-aging');

