SELECT 'one-time-recharger-churn-risk', 'Case: One-Time Rechargers', 'case_study', 'Medium', 'Telco',
       'Aggregation', ARRAY['having','join','churn']::text[], '**Scenario.** Retention flags subscribers who recharged exactly **once** in June as churn risks — one top-up and silence.

Return `name`, plan name (`plan_name`), and their single recharge `amount`, ordered by amount descending.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'telco_network'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'telco_network'), ''), 'SELECT s.name, p.name AS plan_name, MAX(r.amount) AS amount
FROM subscribers s
JOIN plans p ON p.plan_id = s.plan_id
JOIN recharges r ON r.sub_id = s.sub_id
GROUP BY s.sub_id, s.name, p.name
HAVING COUNT(r.recharge_id) = 1
ORDER BY amount DESC;',
       '["Group per subscriber and count recharges","HAVING COUNT(...) = 1 keeps one-time rechargers","With exactly one recharge, MAX(amount) is that recharge"]'::jsonb, '[]'::jsonb, NULL,
