SELECT 'fraud-week-1-damage-count', 'Day 1: Count the Damage', 'code', 'Easy', 'Fintech',
       'Aggregation', ARRAY['group-by','having']::text[], 'First, a headcount. For every user with at least one failed or reversed transaction, return `user_id` and the number of such transactions (`bad_txns`), worst first.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), 'SELECT user_id, COUNT(*) AS bad_txns
FROM transactions
WHERE status IN (''failed'',''reversed'')
GROUP BY user_id
ORDER BY bad_txns DESC, user_id;',
       '["Filter to the two bad statuses first","GROUP BY user_id and COUNT(*)"]'::jsonb, '[]'::jsonb, NULL,
       (SELECT id FROM public.careerprep_questions WHERE slug = 'mission-fraud-week'), 0, NULL, 70
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'fraud-week-1-damage-count');

INSERT INTO public.careerprep_questions
  (slug, title, question_type, difficulty, industry, category, tags, content_md,
   schema_sql, initial_sql, solution_sql, hints, options, correct_option,
   parent_id, order_index, time_limit_secs, success_rate)
SELECT 'fraud-week-2-retry-pairs', 'Day 2: Find the Retry Pairs', 'code', 'Medium', 'Fintech',
       'Self Joins', ARRAY['self-join','time-window']::text[], 'Day 1 showed the failures. Now check which of them were **retried and succeeded**: find pairs where the same user re-attempted the same type and amount within 30 minutes of a failure and it succeeded.

Return the failed `txn_id` (`failed_txn`), the successful `txn_id` (`retry_txn`), `user_id`, and the amount.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), 'SELECT f.txn_id AS failed_txn, s.txn_id AS retry_txn, f.user_id, f.amount
FROM transactions f
JOIN transactions s
  ON s.user_id = f.user_id
 AND s.txn_type = f.txn_type
 AND s.amount = f.amount
 AND s.status = ''success''
 AND s.txn_at > f.txn_at
 AND s.txn_at <= f.txn_at + INTERVAL ''30 minutes''
WHERE f.status = ''failed'';',
       '["Join transactions to itself on user, type and amount","The retry happens after the failure: s.txn_at > f.txn_at","Bound the window with an INTERVAL"]'::jsonb, '[]'::jsonb, NULL,
       (SELECT id FROM public.careerprep_questions WHERE slug = 'mission-fraud-week'), 1, NULL, 41
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'fraud-week-2-retry-pairs');

