SELECT 'fraud-week-3-district-exposure', 'Day 3: District Exposure', 'code', 'Medium', 'Fintech',
       'Joins', ARRAY['join','group-by']::text[], 'Leadership asks: *where* is this happening? Sum the amount of failed and reversed transactions per user district.

Return `district` and `exposed_amount`, highest first.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), 'SELECT u.district, SUM(t.amount) AS exposed_amount
FROM users u
JOIN transactions t ON t.user_id = u.user_id
WHERE t.status IN (''failed'',''reversed'')
GROUP BY u.district
ORDER BY exposed_amount DESC;',
       '["The district lives on users — join through user_id","Same bad-status filter as Day 1, then GROUP BY district"]'::jsonb, '[]'::jsonb, NULL,
       (SELECT id FROM public.careerprep_questions WHERE slug = 'mission-fraud-week'), 2, NULL, 55
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'fraud-week-3-district-exposure');

INSERT INTO public.careerprep_questions
  (slug, title, question_type, difficulty, industry, category, tags, content_md,
   schema_sql, initial_sql, solution_sql, hints, options, correct_option,
   parent_id, order_index, time_limit_secs, success_rate)
SELECT 'fraud-week-4-review-list', 'Day 4: The Manual Review List', 'code', 'Hard', 'Fintech',
       'Conditional Aggregation', ARRAY['case-when','having','ratio']::text[], 'Final step: cash-out-heavy wallets are the classic mule pattern. Flag users whose total successful cash-out exceeds **50%** of their total successful cash-in.

Return `user_id`, `name`, `cash_in_total`, `cash_out_total`. Only include users with at least one successful cash-in.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), 'SELECT u.user_id, u.name,
       SUM(CASE WHEN t.txn_type = ''cash_in''  THEN t.amount ELSE 0 END) AS cash_in_total,
       SUM(CASE WHEN t.txn_type = ''cash_out'' THEN t.amount ELSE 0 END) AS cash_out_total
FROM users u
JOIN transactions t ON t.user_id = u.user_id
WHERE t.status = ''success''
GROUP BY u.user_id, u.name
HAVING SUM(CASE WHEN t.txn_type = ''cash_in'' THEN t.amount ELSE 0 END) > 0
   AND SUM(CASE WHEN t.txn_type = ''cash_out'' THEN t.amount ELSE 0 END)
     > 0.5 * SUM(CASE WHEN t.txn_type = ''cash_in'' THEN t.amount ELSE 0 END);',
       '["Conditional SUMs give cash-in and cash-out in one pass","The ratio test goes in HAVING, not WHERE","Guard against users with zero cash-in"]'::jsonb, '[]'::jsonb, NULL,
       (SELECT id FROM public.careerprep_questions WHERE slug = 'mission-fraud-week'), 3, 1800, 31
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'fraud-week-4-review-list');

