SELECT 'postmortem-2-aov', 'Step 2: Average Order Value', 'code', 'Medium', 'E-Commerce',
       'Aggregation', ARRAY['avg','subquery']::text[], 'The funnel looked healthy. Now the money: what was the **average order value** of delivered orders? Return one row with `aov` (average of per-order revenue), rounded to 2 decimals.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'ecommerce_shop'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'ecommerce_shop'), ''), 'SELECT ROUND(AVG(order_revenue), 2) AS aov FROM (
  SELECT o.order_id, SUM(oi.quantity * oi.unit_price) AS order_revenue
  FROM orders o
  JOIN order_items oi ON oi.order_id = o.order_id
