SELECT 'postmortem-3-bestseller', 'Step 3: The Bestseller', 'code', 'Medium', 'E-Commerce',
       'Joins', ARRAY['join','group-by','limit']::text[], 'Marketing wants the hero product for the recap deck. Among **delivered** orders, return the product `name` and total units sold (`units_sold`) of the single best-selling product by units.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'ecommerce_shop'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'ecommerce_shop'), ''), 'SELECT p.name, SUM(oi.quantity) AS units_sold
FROM products p
JOIN order_items oi ON oi.product_id = p.product_id
JOIN orders o ON o.order_id = oi.order_id
WHERE o.status = ''delivered''
GROUP BY p.name
ORDER BY units_sold DESC
LIMIT 1;',
       '["Units are SUM(quantity), not revenue","ORDER BY DESC LIMIT 1 for the single winner"]'::jsonb, '[]'::jsonb, NULL,
       (SELECT id FROM public.careerprep_questions WHERE slug = 'mission-campaign-postmortem'), 2, NULL, 58
