INSERT INTO public.careerprep_questions
  (slug, title, question_type, difficulty, industry, category, tags, content_md,
   schema_sql, initial_sql, solution_sql, hints, options, correct_option,
   parent_id, order_index, time_limit_secs, success_rate)
SELECT 'postmortem-4-repeat-buyers', 'Step 4: Repeat Buyers Carry the Campaign', 'code', 'Hard', 'E-Commerce',
       'Aggregation', ARRAY['having','multi-join']::text[], 'The CMO''s hypothesis: repeat buyers drove the campaign. Find customers with **2 or more delivered orders**; return `name`, their delivered order count (`orders_count`), and total delivered revenue (`total_revenue`), by revenue descending.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'ecommerce_shop'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'ecommerce_shop'), ''), 'SELECT c.name, COUNT(DISTINCT o.order_id) AS orders_count,
       SUM(oi.quantity * oi.unit_price) AS total_revenue
FROM customers c
JOIN orders o ON o.customer_id = c.customer_id
JOIN order_items oi ON oi.order_id = o.order_id
WHERE o.status = ''delivered''
GROUP BY c.customer_id, c.name
HAVING COUNT(DISTINCT o.order_id) >= 2
ORDER BY total_revenue DESC;',
